const b = $('🔔 Webhook G54 (wa_followup)').first().json.body || {};
return [{ json: {
  company_id: Number(b.company_id) || null,
  deal_id: Number(b.deal_id) || null,
  telefono: String(b.telefono || ''),
  nombre: b.nombre || '',
  user_id: b.trigger?.user_id ?? null,
} }];

// No se confía en el teléfono que llega en el body: tiene que ser el del trato, y el
// trato tiene que ser de la empresa del pedido. Así nadie puede usar este webhook
// para mandar WhatsApp a cualquier número.
const p = $('🔧 Leer Pedido').first().json;
const cfg = $('⚙️ Config').first().json;
const raw = $input.first().json || {};
const deal = raw.data || raw;
const digits = s => String(s || '').replace(/\D/g, '');
let motivo = null;
if (!$('🔐 G54: Login').first().json.access_token) motivo = 'No se pudo iniciar sesión en G54.';
else if (!p.company_id || !p.deal_id) motivo = 'Faltan company_id o deal_id.';
else if (!deal || !deal.id) motivo = 'No se encontró el trato en esa empresa.';
else if (Number(deal.company_id) !== p.company_id) motivo = 'El trato no es de esa empresa.';
const tel = digits(p.telefono);
if (!motivo && !/^\d{8,15}$/.test(tel)) motivo = 'El contacto no tiene un número de WhatsApp (por ejemplo, es de Telegram).';
const telTrato = digits(deal.telefono || deal.contact?.phone);
if (!motivo && telTrato && telTrato !== tel) motivo = 'El teléfono no coincide con el del trato.';
if (!motivo && !telTrato && !deal.wa_contact_id) motivo = 'El trato no tiene un teléfono asociado.';
if (!motivo && ['closed', 'lost'].includes(deal.etapa)) motivo = `El trato está en la etapa "${deal.etapa}": no se le hace seguimiento.`;
// Anti-repetición: un clic doble o repetido no manda dos mensajes.
const sd = $getWorkflowStaticData('global');
sd.ultimoEnvio = sd.ultimoEnvio || {};
const ahora = Date.now();
const prev = sd.ultimoEnvio[p.deal_id];
if (!motivo && prev && ahora - prev < cfg.ANTIREPETICION_MIN * 60000) {
  motivo = `Ya se mandó un seguimiento a este lead hace menos de ${cfg.ANTIREPETICION_MIN} minutos.`;
}
if (!motivo) sd.ultimoEnvio[p.deal_id] = ahora;
return [{ json: { puede: !motivo, motivo, telefono: tel, deal_id: p.deal_id, company_id: p.company_id,
                  nombre: p.nombre || deal.nombre || '' } }];

const v = $('🔎 Validar Envío').first().json;
const bot = (() => { try { const j = $('🔑 G54: Datos del bot').first().json; return j.data || j; } catch (e) { return {}; } })();
const msg = bot.msg_followup_24h || '';
let enviado = false, motivo = v.motivo;
if (v.puede) {
  const r = (() => { try { return $('📤 Enviar Seguimiento WhatsApp').first().json; } catch (e) { return {}; } })();
  if (!bot.phone_number_id || !bot.wa_access_token) motivo = 'La empresa no tiene WhatsApp configurado.';
  else if (!msg) motivo = 'La empresa no tiene cargado el mensaje de seguimiento de 24h.';
  else if (r.messages && r.messages[0]?.id) enviado = true;
  else {
    const code = r.error?.code;
    motivo = code === 131047
      ? 'Pasaron más de 24 horas desde el último mensaje del cliente: WhatsApp solo deja escribirle con una plantilla aprobada.'
      : 'WhatsApp rechazó el mensaje' + (r.error?.message ? ': ' + r.error.message : '.');
  }
}
if (!enviado) { const sd = $getWorkflowStaticData('global'); if (sd.ultimoEnvio) delete sd.ultimoEnvio[v.deal_id]; }
return [{ json: { ok: enviado, motivo: enviado ? null : motivo, mensaje: enviado ? msg : null,
                  telefono: v.telefono, deal_id: v.deal_id, company_id: v.company_id, nombre: v.nombre } }];

